Hook.Script:
//configure csv parser
var parser = system.getParser( "ibmdi.CSV" );
parser.setParam ( "csvColumnSeparator", ":" );

var outParser = system.getParser( "ibmdi.Simple" );

//configure connector
var conn = system.getConnector("ibmdi.FileSystem");
conn.setParam ( "name", "test" );
conn.setParam ( "filePath", "examples/scripting/sample.csv" );
conn.setParam ( "ConnectorMode", "Iterator" );
conn.setParam ( "debug", "true" );
conn.setParser (parser);
var inputConnMode = new Packages.com.ibm.di.server.ConnectorMode("Iterator");
conn.initialize ( inputConnMode );


var outConn = system.getConnector("ibmdi.FileSystem");
outConn.setParam ( "name", "xml" );
outConn.setParam ( "filePath", "examples/scripting/output.txt" );
var outputConnMode = new Packages.com.ibm.di.server.ConnectorMode("AddOnly");
outConn.setParser (outParser);
outConn.initialize ( outputConnMode );


//prepare for reading
conn.selectEntries();

var e = conn.getNextEntry();
while ( e!= null)
{
	//main.dump(e);
	outConn.putEntry(e);
	e = conn.getNextEntry();
}

